import pandas as pd,numpy as np
from pymatgen.core import Structure
p=pd.read_csv('nlo_pool.csv')
sel=list(range(1,5))+list(range(8,20))+list(range(31,38))+list(range(40,47))+list(range(50,53))+[57,67,75,76,77,78,81,82,83,84,85,86,93]+list(range(94,100))
cutoffs={('Ga','Se'):2.8,('Ga','S'):2.65,('B','S'):2.1,('Be','Se'):2.7,('As','S'):2.7,('Al','S'):2.6,('Al','Se'):2.8,('Zn','S'):2.7,('Zn','Se'):2.85,('Sn','Cl'):3.3,('Ge','Cl'):2.8}
for i in sel:
 r=p.iloc[i-1]; s=Structure.from_str(r.poscar,fmt='poscar'); ts={}
 for a in s:
  for n in s.get_neighbors(a,3.3):
   pair=(str(a.specie),str(n.specie))
   if pair not in cutoffs or n.nn_distance>cutoffs[pair]:continue
   v=(n.coords-a.coords)/n.nn_distance
   ts.setdefault(pair,np.zeros((3,3,3)))
   ts[pair]+=np.einsum('i,j,k->ijk',v,v,v)*1000/s.volume
 print(r.candidate_id, r.formula)
 for k,t in ts.items():
  idx=np.unravel_index(abs(t).argmax(),t.shape)
  print(f' {k[0]}-{k[1]} max {abs(t).max():.2f} at {idx} norm {np.linalg.norm(t):.2f}; x3 y3 z3 {t[0,0,0]:.2f} {t[1,1,1]:.2f} {t[2,2,2]:.2f}')
